// ==========================================
// Question Bank Helper & Filter Functions
// ==========================================
export function getAllQuestions() {
    return [...QUESTION_BANK];
}
export function filterQuestions(bank, options) {
    return bank.filter((q) => {
        if (options.subject) {
            const s = options.subject.toLowerCase().trim();
            const matchSubject = q.subject.toLowerCase() === s ||
                (q.subjectId && q.subjectId.toLowerCase().includes(s)) ||
                s.includes(q.subject.toLowerCase());
            if (!matchSubject)
                return false;
        }
        if (options.grade !== undefined && q.grade !== options.grade) {
            return false;
        }
        if (options.stage && q.stage !== options.stage) {
            return false;
        }
        if (options.stream && q.stream && q.stream !== 'general' && q.stream !== options.stream) {
            return false;
        }
        if (options.chapter !== undefined && q.chapter !== options.chapter) {
            return false;
        }
        if (options.type && q.type !== options.type) {
            return false;
        }
        if (options.difficulty && q.difficulty !== options.difficulty) {
            return false;
        }
        if (options.isMinisterial !== undefined && q.isMinisterial !== options.isMinisterial) {
            return false;
        }
        if (options.searchTerm) {
            const term = options.searchTerm.toLowerCase().trim();
            const matchText = q.text.toLowerCase().includes(term) ||
                q.topic.toLowerCase().includes(term) ||
                q.modelAnswer.toLowerCase().includes(term) ||
                q.tags.some((t) => t.toLowerCase().includes(term));
            if (!matchText)
                return false;
        }
        if (options.tags && options.tags.length > 0) {
            const hasAllTags = options.tags.every((tag) => q.tags.some((t) => t.toLowerCase() === tag.toLowerCase()));
            if (!hasAllTags)
                return false;
        }
        return true;
    });
}
export function getMinisterialQuestions(bank, subject) {
    return filterQuestions(bank, { subject, isMinisterial: true });
}
export function getQuestionsByChapter(bank, subject, chapter) {
    return filterQuestions(bank, { subject, chapter });
}
export function searchQuestions(bank, keyword) {
    return filterQuestions(bank, { searchTerm: keyword });
}
/**
 * Supports appending a question from bank into current exam draft with Arabic auto-renumbering:
 * س1/, س2/, س3/, etc.
 */
export function renumberDraftQuestions(draft, newQuestionText) {
    const nextQuestionNumber = draft.length + 1;
    const formattedQuestion = `س${nextQuestionNumber}/ ${newQuestionText.replace(/^س\d+\/\s*/, '')}`;
    return [...draft, formattedQuestion];
}
